package com.aoo.bcg.poker;
import com.aoo.bcg.gamespi.*;import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class HbpdkNineStageAcceptanceTest{
	 @Test void nineStagesOptionsAndReplay(){HbpdkGameProvider p=new HbpdkGameProvider();assertEquals(0,ServiceLoader.load(GameProvider.class).stream().filter(x->x.type()==HbpdkGameProvider.class).count());GameRoomHandle room=p.roomFactory().create(new RoomCreationContext(89001,10,Map.of("playerNum",2,"cardNum",2,"shuffleSeed",89)));GameCommandHandler h=p.commandHandler().orElseThrow();h.handle(room,q("join_req",1,0,10,Map.of()));h.handle(room,q("join_req",2,1,20,Map.of()));h.handle(room,q("ready_req",3,0,10,Map.of()));h.handle(room,q("ready_req",4,1,20,Map.of()));HbpdkSession s=(HbpdkSession)room.requireAuthoritativeSession();assertEquals(16,own(s,10,0).size());assertEquals(16,s.viewFor(10).get("stockCount"));assertTrue(s.invariantViolations().isEmpty());StatePayload base=StatePayload.copyOf(s.authoritativeState());int at=s.recordedEvents().size(),turn=(Integer)s.viewFor(10).get("currentSeat");long player=turn==0?10:20;assertTrue(own(s,player,turn).contains(HbpdkRules.HEART3));h.handle(room,q("play_req",5,turn,player,Map.of("cards",List.of(HbpdkRules.HEART3))));Map<String,Object>saved=s.authoritativeState();AuthoritativeGameSession restored=p.restoreAuthoritativeSession(saved).orElseThrow();assertEquals(saved,restored.authoritativeState());assertEquals(s.viewFor(20),p.reconnectViewProvider().orElseThrow().buildFor(20,new GameRoomHandle(89001,89,HbpdkGameProvider.VERSION,restored)));assertEquals(saved,p.eventReplayProvider().orElseThrow().replay(base,s.recordedEvents().subList(at,s.recordedEvents().size())).asMap());assertThrows(IllegalArgumentException.class,()->HbpdkSession.replay(StatePayload.copyOf(Map.of("stateVersion",0)),List.of(Map.of("version",2,"after",saved))));assertEquals(12,HbpdkOptions.from(Map.of("cardNum",0)).handSize());assertEquals(15,HbpdkOptions.from(Map.of("cardNum",1)).handSize());assertEquals(HbpdkRules.SPADE3,HbpdkRules.family(HbpdkOptions.from(Map.of("xianchu",3))).profile().requiredFirstCard());assertEquals("SPECIAL_TRIPLE_BOMB",HbpdkRules.family(HbpdkOptions.from(Map.of("kexuanwanfa",List.of(4)))).rules().recognize(List.of(114,214,314),new PaoDeKuaiContext(false,8,List.of(114,214,314))).type());}
 @Test void fixedDealsUseLegacyDeckAndShowOptionNeverLeaksHands(){HbpdkSession two=start(Map.of("playerNum",2,"cardNum",1,"kexuanwanfa",List.of(4,11,13)));assertEquals(15,own(two,10,0).size());assertEquals(15,own(two,20,1).size());assertEquals(15,two.viewFor(10).get("stockCount"));assertEquals(Boolean.TRUE,two.viewFor(10).get("showRemainingCardCount"));assertEquals(Collections.nCopies(15,0),seatCards(two.viewFor(10),1));assertFalse(allCards(two).contains(PokerCardCodec.fromLegacyNibble(0x1e)));assertFalse(allCards(two).contains(PokerCardCodec.fromLegacyNibble(0x2e)));assertFalse(allCards(two).contains(PokerCardCodec.fromLegacyNibble(0x0d)));HbpdkSession three=start(Map.of("playerNum",3,"cardNum",0,"kexuanwanfa",List.of(4,13)));assertEquals(12,own(three,30,2).size());assertEquals(12,three.viewFor(10).get("stockCount"));assertEquals(Boolean.FALSE,three.viewFor(10).get("showRemainingCardCount"));assertTrue(three.invariantViolations().isEmpty());}
 @Test void everyLiveRuleSwitchChangesAuthority(){PaoDeKuaiContext terminal=new PaoDeKuaiContext(false,5,List.of(107,207,307));CardCombination triple=new CardCombination("TRIPLE",7,List.of(107,207,307)),previous=new CardCombination("TRIPLE_WITH_SINGLES",6,List.of(106,206,306,109,110));assertFalse(HbpdkRules.family(HbpdkOptions.from(Map.of("kexuanwanfa",List.of(4)))).rules().canBeat(triple,previous,terminal));assertTrue(HbpdkRules.family(HbpdkOptions.from(Map.of("kexuanwanfa",List.of(4,13)))).rules().canBeat(triple,previous,terminal));SettlementPayload disabled=finished(Map.of("zhadansuanfa",2,"zhadanfenshu",1)).settlement(1,HbpdkGameProvider.VERSION);SettlementPayload winnerDouble=finished(Map.of("zhadansuanfa",1,"zhadanfenshu",0)).settlement(1,HbpdkGameProvider.VERSION);SettlementPayload winnerAdd=finished(Map.of("zhadansuanfa",1,"zhadanfenshu",1)).settlement(1,HbpdkGameProvider.VERSION);assertEquals(5L,disabled.scoreDelta().get(10L));assertEquals(10L,winnerDouble.scoreDelta().get(10L));assertEquals(15L,winnerAdd.scoreDelta().get(10L));assertEquals(0L,winnerAdd.scoreDelta().values().stream().mapToLong(Long::longValue).sum());assertThrows(IllegalArgumentException.class,()->HbpdkOptions.from(Map.of("kexuanwanfa",List.of(99))));}
	 private static HbpdkSession start(Map<String,Object>rules){HbpdkOptions o=HbpdkOptions.from(rules);HbpdkSession s=new HbpdkSession(89001,10,89,o);s.execute(q("join_req",1,0,10,Map.of()));s.execute(q("join_req",2,1,20,Map.of()));if(o.players()==3)s.execute(q("join_req",3,2,30,Map.of()));s.execute(q("ready_req",4,0,10,Map.of()));s.execute(q("ready_req",5,1,20,Map.of()));if(o.players()==3)s.execute(q("ready_req",6,2,30,Map.of()));return s;}
 private static HbpdkSession finished(Map<String,Object>rules){HbpdkSession live=start(new LinkedHashMap<>(){{put("playerNum",2);put("cardNum",2);putAll(rules);}});Map<String,Object>s=new LinkedHashMap<>(live.authoritativeState());s.put("state",new PokerTurnState(Map.of(0,List.of(),1,List.of(104,105,106,107,108)),0,null,-1,Set.of(),true,0));s.put("bombs",Map.of(0,1,1,0));return HbpdkSession.restore(s);}
 @SuppressWarnings("unchecked")private static List<Integer>seatCards(Map<String,Object>v,int seat){return(List<Integer>)((Map<String,Object>)((Map<Integer,Object>)v.get("seats")).get(seat)).get("cards");}private static Set<Integer>allCards(HbpdkSession s){Set<Integer>c=new HashSet<>();PokerTurnState p=(PokerTurnState)s.authoritativeState().get("state");p.hands().values().forEach(c::addAll);c.addAll((List<Integer>)s.authoritativeState().get("stock"));return c;}
 @SuppressWarnings("unchecked")private static List<Integer>own(AuthoritativeGameSession s,long p,int seat){return(List<Integer>)((Map<String,Object>)((Map<Integer,Object>)s.viewFor(p).get("seats")).get(seat)).get("cards");}private static GameCommandRequest q(String id,long n,int seat,long p,Map<String,Object>b){return new GameCommandRequest(id,"hb-"+n,n,89001,0,HbpdkGameProvider.VERSION,String.valueOf(p),seat,b);}
}
